"""Write the round's Russian experiment summary from verified numeric outputs."""
from study import D,get


def num(x, precision=2):
    return f"{x:.{precision}f}".replace(".",",")


def main():
    r=get(D/"results.json");p=get(D/"panel.json");c=get(D/"costs.json");budget=get(D/"reader-boundaries.json")
    primary=r["paired"]["router-linked_dense"]
    f1,sup=1,2
    ci=primary["ci"][f1];effect=primary["pp"][f1]
    if ci[0]>0:
        verdict="По первичной метрике выигрыш над постоянным предпочтением упомянутого заголовка подтвердился."
    elif ci[1]<0:
        verdict="По первичной метрике маршрутизация ухудшила F1 по сравнению с постоянным предпочтением упомянутого заголовка."
    else:
        verdict="Первичная проверка оставляет преимущество над постоянным предпочтением упомянутого заголовка неопределённым."
    names={"dense":"Плотный поиск","adaptive":"Порог, обученный на 2Wiki","linked_dense":"Всегда предпочитать упоминание","router":"Маршрутизация по словам вопроса"}
    table=[]
    for arm,label in names.items():
        vals=r["means_pct"][arm]
        table.append(f'| {label} | {num(vals[1])} | {num(vals[0])} | {num(vals[2])} | {num(vals[3])} | {r["source_arms"][arm]} |')
    types=[]
    for k,v in r["strata"].items():
        m=v["means_pct"]
        types.append(f'| {k} | {v["n"]} | {num(m["dense"][1])} | {num(m["adaptive"][1])} | {num(m["linked_dense"][1])} | {num(m["router"][1])} |')
    f=r["flags"];marked=sum(v for k,v in f.items() if k.startswith("True|"))
    sig=r["primary_randomization"];w=primary["wins"][1];l=primary["losses"][1]
    out=f'''# Можно ли выбирать графовую политику по формулировке вопроса?

На новой панели из {r["n"]} HotpotQA distractor первичная парная разность **{num(effect,3)} п.п. Answer F1** с 95% ДИ **[{num(ci[0],3)}; {num(ci[1],3)}]**. {verdict} Исходная гипотеза пришла из предыдущих 640 вопросов, где граф сильнее помогал при переходе через промежуточную сущность, а для сравнения двух сущностей такая связь часто вела в сторону. [Фиксированный протокол](PROTOCOL_RU.md) · [Предыдущая панель](../transfer/REPORT_RU.md)

| Выбор второго документа | Answer F1 | EM, % | Все опорные заголовки, % | Средняя доля опор, % | Смен от плотного поиска |
|---|---:|---:|---:|---:|---:|
{chr(10).join(table)}

Решение использовало только слова вопроса, например *both*, *same*, *older*, и заранее заданный признак вопросительной конструкции с *and/or*. В {marked} случаях правило предложило обычный семантический поиск, в остальных — приоритет упомянутого адреса. Только в **{r["switched"]}** из {r["n"]} случаев две политики действительно выбирали разные документы. При сравнении с безусловным переходом F1 вырос на {w} вопросах, снизился на {l}, совпал на {r["n"]-w-l}. Двусторонняя знаковая рандомизация по величинам парных разностей дала p = {num(sig["p"],6)}, число знаковых наборов {sig["draws"]}. Для доли случаев с получением всех заголовков разность составила {num(primary["pp"][sup])} п.п. [{num(primary["ci"][sup][0])}; {num(primary["ci"][sup][1])}]. Все ДИ получены 10 000 парными перевыборками первых документов. [Адреса до открытия эталонов](router-choices.json.gz) · [Поштучные исходы](outcomes.json.gz) · [Сводка](results.json)

### Разбор типов вопросов

| Метка авторов | N | Плотный поиск F1 | Порог F1 | Безусловный переход F1 | Маршрутизатор F1 |
|---|---:|---:|---:|---:|---:|
{chr(10).join(types)}

Среди сравнительных вопросов текстовый признак сработал в {f.get("True|comparison",0)} из {r["strata"].get("comparison",{}).get("n",0)}, а среди вопросов типа bridge — в {f.get("True|bridge",0)} из {r["strata"].get("bridge",{}).get("n",0)}. Метка типа доступна только для последующего разбора. Знаменатель основного сравнения включает все {r["n"]} вопросов независимо от активации признака.

### Данные и границы измерения

Панель отобрана по фиксированной хеш-сортировке из обоих публичных train-шардов HotpotQA, содержащих 90 447 вопросов. Пропущены {p["rejections"].get("first",0)} повторных первых документов и {p["rejections"].get("question",0)} известных или повторных вопросов. При формировании учтены {p["historical_questions"]} прошлых вопросов и {p["historical_documents"]} документов. Новые первые документы уникальны, а у {p["shared_other_doc_queries"]} вопросов хотя бы один другой документ уже встречался. Принадлежность этих примеров к данным предобучения моделей неизвестна. [Реестр панели](panel.json)

Три базовых варианта и маршрутизатор используют Qwen3-Embedding-8B Q4_K_M для адресации и Qwen3-4B-Instruct-2507 Q4_K_M для ответа. Первый документ выбирается прежним BM25. Для чтения использованы две страницы на эпизод и один и тот же фактический бюджет у всех вариантов, {budget["prompt_tokens"]} токенов за панель на политику. Стенд выравнивает длины с помощью предвычисленных длин фрагментов; это число доступных модели фрагментов, физические обращения СУБД здесь не измерялись. Для {4*r["n"]} логических ответов хватило {c["model_calls"]} уникальных полных промптов, затем выполнены ещё {c["repeats"]} проверочных вызова модели. На RTX 3090 генерация и повторы заняли {num(c["wall_seconds"])} с. Эмбеддинги считались отдельно. [Токены и бюджеты](reader-boundaries.json) · [Ресурсы](costs.json)

Официальный HotpotQA eval пересчитал Answer F1/EM на всём наборе. Независимая проверка подтвердила все {r["n"]*4} комбинации вопроса и метода, исходя из сохранённых токенов, ответов, адресов и эталонных заголовков. Оценка относится к будущим вопросам при том же специально ограниченном двухшаговом интерфейсе. [Воспроизведение](REPRODUCE_RU.md) · [Условия официальной оценки HotpotQA](https://hotpotqa.github.io/)
'''
    old=r["paired"]["adaptive-dense"]
    out+=f'\nНа этой независимой панели прежний порог 2Wiki снова улучшил F1 в сравнении с плотным поиском на **{num(old["pp"][1])} п.п. [{num(old["ci"][1][0])}; {num(old["ci"][1][1])}]**. Полный набор опорных заголовков находился на {num(old["pp"][2])} п.п. чаще. Эти вторичные результаты дополняют подтверждающую проверку нового маршрутизатора. [Все парные разности](results.json)\n'
    sensitivity=get(D/"overlap-sensitivity.json")
    for key,label in [("hotpot_640","Порог минус dense на предыдущих 640"),("hotpot_1280","Маршрутизатор минус безусловный переход на новых 1 280")]:
        z=sensitivity[key]
        out+=f'\n{label}. При объединении вопросов по общим фактически выбранным документам получено {z["components"]} компонент. Наибольшая содержит {z["biggest"]} вопросов. Дополнительный 95% ДИ по компонентам — [{num(z["cluster_ci"][0])}; {num(z["cluster_ci"][1])}] п.п. [Проверка повторного использования источников](overlap-sensitivity.json)\n'
    (D/"REPORT_RU.md").write_text(out,encoding="utf8")


if __name__=="__main__":main()
